use std::mem::{align_of, offset_of, size_of};

#[repr(C)]
struct CLayout {
    a: u8,
    b: u32,
    c: u16,
}

struct RustLayout {
    a: u8,
    b: u32,
    c: u16,
}

fn main() {
    println!("repr(C): size {}, align {}", size_of::<CLayout>(), align_of::<CLayout>());
    println!("offsets a={} b={} c={}", offset_of!(CLayout, a), offset_of!(CLayout, b), offset_of!(CLayout, c));
    println!("default: size {}", size_of::<RustLayout>());
    println!("offsets a={} b={} c={}", offset_of!(RustLayout, a), offset_of!(RustLayout, b), offset_of!(RustLayout, c));
}

use std::ffi::{CStr, c_char, c_int, c_long};

#[repr(C)]
#[derive(Debug)]
struct DivT {
    quot: c_int,
    rem: c_int,
}

unsafe extern "C" {
    safe fn sqrt(x: f64) -> f64; // defined for every input
    fn abs(x: c_int) -> c_int; // abs(INT_MIN) is undefined
    fn div(n: c_int, d: c_int) -> DivT; // div by 0 is undefined
    fn strtol(s: *const c_char, end: *mut *mut c_char, base: c_int) -> c_long;
}

fn main() {
    println!("sqrt(2) = {}", sqrt(2.0));
    // SAFETY: -42 is not INT_MIN.
    println!("abs(-42) = {}", unsafe { abs(-42) });
    // SAFETY: the divisor is not zero and the quotient fits.
    println!("{:?}", unsafe { div(17, 5) });

    let text: &CStr = c"0x1F rest";
    let mut end: *mut c_char = std::ptr::null_mut();
    // SAFETY: text is NUL-terminated; strtol sets end to a position inside it.
    let n = unsafe { strtol(text.as_ptr(), &mut end, 0) };
    let used = end as usize - text.as_ptr() as usize;
    let rest = unsafe { CStr::from_ptr(end) };
    println!("{n} (used {used} bytes, rest {rest:?})");
}

use std::ffi::{CStr, CString, c_char, c_int};

unsafe extern "C" {
    fn strlen(s: *const c_char) -> usize;
    fn strchr(s: *const c_char, c: c_int) -> *mut c_char;
}

fn main() {
    let owned = CString::new("hello, world").expect("no NUL inside");
    let len = unsafe { strlen(owned.as_ptr()) };
    println!("strlen = {len}");

    let p = unsafe { strchr(owned.as_ptr(), b',' as c_int) };
    if !p.is_null() {
        // SAFETY: strchr returns a pointer into `owned`, which is still alive.
        let tail = unsafe { CStr::from_ptr(p) };
        println!("from comma: {:?}", tail.to_str());
    }

    println!("{:?}", CString::new("bad\0string"));
    let bytes = owned.as_bytes_with_nul();
    println!("{} bytes with NUL, last = {}", bytes.len(), bytes[bytes.len() - 1]);
    let back: String = owned.into_string().unwrap();
    println!("{back}");
}

use std::cmp::Ordering;
use std::ffi::{c_int, c_void};

unsafe extern "C" {
    fn qsort(
        base: *mut c_void,
        n: usize,
        size: usize,
        cmp: extern "C" fn(*const c_void, *const c_void) -> c_int,
    );
}

extern "C" fn by_abs(a: *const c_void, b: *const c_void) -> c_int {
    // SAFETY: qsort passes pointers to elements of our i32 array.
    let (a, b) = unsafe { (*(a as *const i32), *(b as *const i32)) };
    match a.unsigned_abs().cmp(&b.unsigned_abs()) {
        Ordering::Less => -1,
        Ordering::Equal => 0,
        Ordering::Greater => 1,
    }
}

fn main() {
    let mut v = [5, -12, 3, -1, 8, -7];
    unsafe { qsort(v.as_mut_ptr().cast(), v.len(), size_of::<i32>(), by_abs) };
    println!("{v:?}");
}

use std::ffi::{CStr, CString, c_char, c_int};
use std::io;

#[repr(C)]
struct FILE {
    _private: [u8; 0],
}

unsafe extern "C" {
    fn fopen(path: *const c_char, mode: *const c_char) -> *mut FILE;
    fn fputs(s: *const c_char, f: *mut FILE) -> c_int;
    fn fclose(f: *mut FILE) -> c_int;
}

/// Owns an open C `FILE *`; closing happens in Drop.
struct CFile(*mut FILE);

impl CFile {
    fn create(path: &str) -> io::Result<CFile> {
        let path = CString::new(path).map_err(|e| io::Error::new(io::ErrorKind::InvalidInput, e))?;
        let f = unsafe { fopen(path.as_ptr(), c"w".as_ptr()) };
        if f.is_null() { Err(io::Error::last_os_error()) } else { Ok(CFile(f)) }
    }

    fn write(&mut self, s: &CStr) -> io::Result<()> {
        if unsafe { fputs(s.as_ptr(), self.0) } < 0 { Err(io::Error::last_os_error()) } else { Ok(()) }
    }
}

impl Drop for CFile {
    fn drop(&mut self) {
        unsafe { fclose(self.0) };
    }
}

fn main() -> io::Result<()> {
    let path = std::env::temp_dir().join(format!("ffi-{}.txt", std::process::id()));
    {
        let mut f = CFile::create(path.to_str().unwrap())?;
        f.write(c"written by C's stdio\n")?;
        f.write(c"closed by Drop\n")?;
    } // fclose runs here and flushes the buffer
    print!("{}", std::fs::read_to_string(&path)?);
    std::fs::remove_file(&path)?;
    println!("{:?}", CFile::create("/no/such/dir/x.txt").err().map(|e| e.kind()));
    Ok(())
}

use std::panic;

/// C signature: int checked_div(int a, int b, int *out);
/// Returns 0 on success, -1 on a panic, -2 if out is NULL.
#[unsafe(no_mangle)]
pub extern "C" fn checked_div(a: i32, b: i32, out: *mut i32) -> i32 {
    if out.is_null() {
        return -2;
    }
    match panic::catch_unwind(|| a / b) {
        Ok(v) => {
            // SAFETY: the caller promises out points to a writable int.
            unsafe { *out = v };
            0
        }
        Err(_) => -1,
    }
}

fn main() {
    panic::set_hook(Box::new(|_| {})); // keep the panic message out of the output
    let mut out = 0;
    println!("{} {}", checked_div(17, 5, &mut out), out);
    println!("{}", checked_div(1, 0, &mut out));
    println!("{}", checked_div(1, 1, std::ptr::null_mut()));
}

